270: 					case WM_MBUTTONDOWN:
271: 						button = 2;
272: 						state = SDL_PRESSED;
273: 						break;
274: 					case WM_MBUTTONUP:
275: 						button = 2;
276: 						state = SDL_RELEASED;
277: 						break;
278: 					case WM_RBUTTONDOWN:
279: 						button = 3;
280: 						state = SDL_PRESSED;
281: 						break;
282: 					case WM_RBUTTONUP:
283: 						button = 3;
284: 						state = SDL_RELEASED;
285: 						break;
286: 					default:
287: 						/* Eh? Unknown button? */
288: 						return(0);
289: 				}
290: 				if ( state == SDL_PRESSED ) {
291: 					/* Grab mouse so we get up events */
292: 					if ( ++mouse_pressed > 0 ) {
293: 						SetCapture(hwnd);
294: 					}
295: 				} else {
296: 					/* Release mouse after all up events */
297: 					if ( --mouse_pressed <= 0 ) {
298: 						ReleaseCapture();
299: 						mouse_pressed = 0;
300: 					}
301: 				}
302: 				if ( mouse_relative ) {
303: 				/*	RJR: March 28, 2000
304: 					report internal mouse position if in relative mode */
305: 					x = 0; y = 0;
306: 				} else {
307: 					x = (Sint16)LOWORD(lParam);
308: 					y = (Sint16)HIWORD(lParam);
309: 				}
310: 				posted = SDL_PrivateMouseButton(
311: 							state, button, x, y);
312: 			}
313: 		}
