317: 		/* This message is sent as a way for us to "check" the values
318: 		 * of a position change.  If we don't like it, we can adjust
319: 		 * the values before they are changed.
320: 		 */
321: 		case WM_GETMINMAXINFO: {
322: 			MINMAXINFO *info;
323: 			RECT        size;
324: 			int x, y;
325: 			int width;
326: 			int height;
327: 
328: 			/* We don't want to clobber an internal resize */
329: 			if ( SDL_resizing )
330: 				return(0);
331: 
332: 			/* We allow resizing with the SDL_RESIZABLE flag */
333: 			if ( SDL_PublicSurface &&
334: 				(SDL_PublicSurface->flags & SDL_RESIZABLE) ) {
335: 				return(0);
336: 			}
337: 
338: 			/* Get the current position of our window */
339: 			GetWindowRect(SDL_Window, &size);
340: 			x = size.left;
341: 			y = size.top;
342: 
343: 			/* Calculate current width and height of our window */
344: 			size.top = 0;
345: 			size.left = 0;
346: 			if ( SDL_PublicSurface != NULL ) {
347: 				size.bottom = SDL_PublicSurface->h;
348: 				size.right = SDL_PublicSurface->w;
349: 			} else {
350: 				size.bottom = 0;
351: 				size.right = 0;
352: 			}
353: 			AdjustWindowRect(&size, GetWindowLong(hwnd, GWL_STYLE),
354: 									FALSE);
355: 			width = size.right - size.left;
356: 			height = size.bottom - size.top;
357: 
358: 			/* Fix our size to the current size */
359: 			info = (MINMAXINFO *)lParam;
360: 			info->ptMaxSize.x = width;
361: 			info->ptMaxSize.y = height;
362: 			info->ptMaxPosition.x = x;
363: 			info->ptMaxPosition.y = y;
364: 			info->ptMinTrackSize.x = width;
